// wf-review-feed — READ-ONLY GET. Serves the recently-staged FRESHNESS
// proposals (DR-0072) as JSON so the in-app Governor 'Review' tab can show what
// the loop is flowing (DR-0061: surfaces are live views of real flow; DR-0065:
// the app is the primary artifact). Header-token auth (fail-closed).
//
// SCOPE: freshness proposals ONLY -- summaries of PUBLIC web links, low
// sensitivity. Family feedback is family-PRIVATE; its canonical home is the
// Supabase feedback table (read in-app via RLS), so it is deliberately NOT
// served here. Keeping private data off this token-gated endpoint is what makes
// a build-time shared token an appropriate speed-bump (N8N-WEBHOOK-AUTH-PATTERN;
// true per-session auth for every webhook arrives at L12).
// No outbound fetch, no mutation -> none of the SSRF surface.

const fs = require('fs');
const path = require('path');

const FRESH_DIR = '/data/finance-events/_freshness';
const TOKEN_FILE = path.join(FRESH_DIR, '.review-token');  // reuse the freshness token
const LIMIT = 25;

const item = $input.first() || {};
const input = item.json || {};
const headers = input.headers || item.headers || {};

// AUTH (fail-closed): header X-Review-Token must match the token file.
let expectedToken = null;
try { expectedToken = fs.readFileSync(TOKEN_FILE, 'utf8').trim(); } catch (_) {}
const got = (headers['x-review-token'] || headers['X-Review-Token'] || '').toString();
if (!expectedToken || got !== expectedToken) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}

function readRecent(dir, n) {
  let names = [];
  try { names = fs.readdirSync(dir).filter(f => f.endsWith('.json') && !f.startsWith('_') && !f.startsWith('.')); } catch (_) { return []; }
  names.sort().reverse();  // ids are timestamp-prefixed -> newest first
  const out = [];
  for (const f of names.slice(0, n)) {
    try { out.push(JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'))); } catch (_) {}
  }
  return out;
}

return [{ json: {
  ok: true,
  generated_at: new Date().toISOString(),
  freshness: readRecent(FRESH_DIR, 100).filter(function (r) { return r && r.status !== 'dismissed'; }).slice(0, LIMIT)
} }];
